(12, 'INC-00001', 14, 77, 3, NULL, 3, '2025-09-03 00:00:00', 0.00, NULL, 1, NULL, '2025-09-04 05:37:50', '2025-09-04 05:37:50', 11, NULL, '2:15 pm del 3 de septiembre de 2025 se celebra reunión IMCR para establecer contramedidas preventivas ante amenaza de huracán Lorena el cual se encuentra en categoría 1 pasando por la zona de Los Cabos, aún no hay presencia de lluvia en Guerrero Negro, se pronostica que las lluvias empezarán la tarde de este día en menos de 40%. Se estarán monitoreando las condiciones climatológicas para ver la evolución del huracán.', NULL, NULL, NULL),
(13, 'INC-00004', 1, 65, 1, NULL, 1, '2025-09-05 00:00:00', 0.00, NULL, 1, NULL, '2025-09-06 01:17:13', '2025-09-06 01:17:13', NULL, 91, 'nada', 'aqui', NULL, NULL),
(14, 'INC-00004', 11, 67, 3, NULL, 1, '2025-09-05 00:00:00', 0.00, NULL, 1, NULL, '2025-09-06 02:11:24', '2025-09-06 02:11:24', NULL, 92, NULL, 'Aqui', NULL, NULL),
(15, 'INC-00002', 18, 67, 3, NULL, 3, '2025-09-05 00:00:00', 0.00, NULL, 1, NULL, '2025-09-06 07:09:49', '2025-09-06 07:09:49', NULL, 100, '15:47 hrs Unidad de línea de transportes EXPRES FRANCO que acudió a planta a descargar refrigeradores, golpeó las puertas de acceso principal (salida de de tractos) al realizar maniobra de reversa. Chofer CERDA CONTRERAS ADRIAN venía con Pablo Gallegos de Refrigeración. Habló a su aseguradora para reponder por los daños, se dio debido aviso al área de Mantenimiento de Edificios. .', 'Accesos Principales de Planta Florido', NULL, NULL),
(16, 'INC-00003', 18, 67, 3, NULL, 1, '2018-01-01 23:00:00', 0.00, NULL, 1, NULL, '2025-09-09 01:05:59', '2025-09-09 01:05:59', NULL, 100, NULL, NULL, NULL, NULL),
