--
-- Estructura para la vista `view_services_spare_parts`
--
DROP TABLE IF EXISTS `view_services_spare_parts`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_services_spare_parts`  AS SELECT `services_spare_parts`.`spare_part_id` AS `spare_part_id`, `spare_parts`.`name` AS `name`, sum(`services_spare_parts`.`quantity`) AS `quantity`, sum(`services_spare_parts`.`quantity` * (`services_spare_parts`.`amount` * (1 + `services_spare_parts`.`iva`))) AS `total` FROM ((`services_spare_parts` left join `spare_parts` on(`spare_parts`.`id` = `services_spare_parts`.`spare_part_id`)) left join `services` on(`services`.`id` = `services_spare_parts`.`service_id`)) WHERE `services`.`status` = 0 AND `services`.`deleted_at` is null GROUP BY `services_spare_parts`.`spare_part_id` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `view_services_vehicles_spare_parts`
--
DROP TABLE IF EXISTS `view_services_vehicles_spare_parts`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_services_vehicles_spare_parts`  AS SELECT `services_vehicles_spare_parts`.`spare_part_id` AS `spare_part_id`, `spare_parts`.`name` AS `name`, sum(`services_vehicles_spare_parts`.`quantity`) AS `quantity`, sum(`services_vehicles_spare_parts`.`quantity` * (`services_vehicles_spare_parts`.`amount` * (1 + `services_vehicles_spare_parts`.`iva`))) AS `total` FROM ((`services_vehicles_spare_parts` left join `spare_parts` on(`spare_parts`.`id` = `services_vehicles_spare_parts`.`spare_part_id`)) left join `services_vehicles` on(`services_vehicles`.`id` = `services_vehicles_spare_parts`.`services_vehicle_id`)) WHERE `services_vehicles`.`status` = 0 AND `services_vehicles`.`deleted_at` is null GROUP BY `services_vehicles_spare_parts`.`spare_part_id` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_services_total`
--
DROP TABLE IF EXISTS `v_services_total`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_services_total`  AS SELECT `s`.`id` AS `service_id`, 0.16 AS `iva`, `s`.`has_iva` AS `has_iva`, coalesce(`s`.`cost`,0) + sum(coalesce(`ssp`.`quantity` * `ssp`.`amount`,0)) AS `total_neto`, (coalesce(`s`.`cost`,0) + sum(coalesce(`ssp`.`quantity` * `ssp`.`amount`,0))) * (1 + if(`s`.`has_iva`,coalesce(`ssp`.`iva`,0.16),0)) AS `total` FROM (`services` `s` left join `services_spare_parts` `ssp` on(`ssp`.`service_id` = `s`.`id`)) GROUP BY `s`.`id` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_services_vehicles_total`
--
DROP TABLE IF EXISTS `v_services_vehicles_total`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_services_vehicles_total`  AS SELECT `s`.`id` AS `service_id`, 0.16 AS `iva`, `s`.`has_iva` AS `has_iva`, coalesce(`s`.`amount`,0) + sum(coalesce(`ssp`.`quantity` * `ssp`.`amount`,0)) AS `total_neto`, (coalesce(`s`.`amount`,0) + sum(coalesce(`ssp`.`quantity` * `ssp`.`amount`,0))) * (1 + if(`s`.`has_iva`,coalesce(`ssp`.`iva`,0.16),0)) AS `total` FROM (`services_vehicles` `s` left join `services_vehicles_spare_parts` `ssp` on(`ssp`.`services_vehicle_id` = `s`.`id`)) GROUP BY `s`.`id` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_weeks_numbers`
